  function userDialog(user){const editing=!!user;const fields=input('name','Full name','Team member name','text',user?.name||'')+input('email','Email','name@business.com','email',user?.email||'')+`<div class="field"><label>Role</label><select name="role" ${user?.id===window.currentUser.id?'disabled':''}>${['Operations','Support','Viewer','Owner/Admin'].map(r=>`<option ${user?.role===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="field full"><label>${editing?'New password (optional)':'Temporary password'}</label><input name="password" type="password" minlength="10" ${editing?'':'required'} autocomplete="new-password" placeholder="${editing?'Leave blank to keep current password':'At least 10 characters'}" /></div>`;dialog(editing?'Edit user':'Create workspace user',fields,async values=>{try{const response=await fetch(editing?`/api/users/${user.id}`:'/api/users',{method:editing?'PUT':'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});const data=await response.json();if(!response.ok){notify(data.error||'Could not save user');return false}log(`${editing?'Workspace user updated':'Workspace user created'}: ${data.user.email} · ${data.user.role}`);save();render();notify(editing?'User updated':'User created');return true}catch{notify('User service is unavailable');return false}})}
  async function deleteWorkspaceUser(user){if(user.id===window.currentUser.id){notify('You cannot delete the account you are signed in with');return}confirmAction('Delete this user?',`Remove ${user.name} (${user.email}) and revoke their workspace access?`,'Delete user',async()=>{try{const response=await fetch(`/api/users/${user.id}`,{method:'DELETE',credentials:'same-origin'});const data=await response.json();if(!response.ok){notify(data.error||'Could not delete user');return}log(`Workspace user deleted: ${user.email}`);await save();render();notify('User deleted')}catch{notify('User service is unavailable')}})}
  function ownerBackupCard(){if(window.currentUser?.role!=='Owner/Admin')return '';return `<div class="card"><div class="card-heading"><div><div class="card-title">Backup & recovery</div><div class="card-note">Download business records or restore a saved copy.</div></div></div><div class="form-actions"><button class="btn" data-action="download-backup">Download backup</button><label class="btn" for="restore-file">Choose backup file</label><input id="restore-file" type="file" accept="application/json,.json" hidden /><span id="restore-file-name" class="card-note">No file selected</span><button class="btn btn-primary" data-action="restore-backup">Restore backup</button></div><div class="field-note">Backups include workspace records, not user accounts or passwords. Store them securely.</div></div>`}
  function settingsPageSecure(){return `${heading('Settings','Workspace preferences and account details.',`${window.currentUser?.role==='Owner/Admin'?'<button class="btn negative" data-action="clear-all-data">Clear all workspace data</button>':''}`)}<div class="grid settings-grid"><div class="card"><div class="card-heading"><div><div class="card-title">Business preferences</div><div class="card-note">Saved to this shared workspace</div></div></div><div class="form-grid"><div class="field"><label>Business name</label><input value="Fragma Alchemy" disabled /></div><div class="field"><label>Currency</label><input value="IDR · Indonesian Rupiah" disabled /></div><div class="field"><label>Timezone</label><select id="timezone"><option>Asia/Jakarta</option><option>Asia/Makassar</option><option>Asia/Jayapura</option></select></div><div class="field"><label>Primary warehouse</label><input id="warehouse" value="${esc(state.settings.warehouse)}" /></div><div class="field"><label>Default low-stock threshold</label><input id="threshold" type="number" min="0" value="${state.settings.threshold}" /></div></div><div class="form-actions"><button class="btn btn-primary" data-action="save-settings">Save preferences</button></div></div><div class="card"><div class="card-heading"><div><div class="card-title">Signed-in account</div><div class="card-note">Managed by the workspace Owner</div></div></div><div class="store-row"><div><div class="store-name">${esc(window.currentUser?.name)}</div><div class="store-detail">${esc(window.currentUser?.email)}</div></div>${badge(window.currentUser?.role)}</div><div class="divider"></div><div class="notice blue">Ask an Owner/Admin to create or change accounts in the Admin panel. Passwords are never displayed.</div></div>${ownerBackupCard()}<div class="card"><div class="card-heading"><div><div class="card-title">Audit log</div><div class="card-note">Recent saved changes and the user who made them</div></div></div><div id="audit-events"><div class="empty-state">Loading audit history…</div></div></div></div>`}
  function systemVersionPage(){return `${heading('System version','Release information and included capabilities for this workspace.')}<div class="version-layout"><section class="card version-hero"><div class="version-hero-top"><div><div class="eyebrow">FRAGMA ALCHEMY · ERP + CRM</div><h2>Version ${esc(systemVersion.number)}</h2><p>Version 1.0.11 is published to GitHub main.</p></div><span class="badge amber">${esc(systemVersion.channel)}</span></div><div class="version-meta"><div><span>Product</span><strong>Fragma Alchemy Operations</strong></div><div><span>Last updated</span><strong>${esc(systemVersion.updated)}</strong></div><div><span>Data store</span><strong>Local SQLite workspace</strong></div></div></section><div class="grid version-grid"><section class="card"><div class="card-heading"><div><div class="card-title">Included modules</div><div class="card-note">Available in this system build</div></div></div><ul class="version-list"><li><strong>Orders & fulfillment</strong><span>Seller export import, order review, status and tracking workflows.</span></li><li><strong>Catalog & batch costing</strong><span>Permanent Main SKU, Tokopedia/TikTok Shop/Shopee SKU references, multi-product import batches, CBM cost allocation, per-batch HPP history and incoming stock receipt.</span></li><li><strong>Inventory</strong><span>Stock counts, adjustments, reorder points and movement history.</span></li><li><strong>Customer operations</strong><span>Customer records with WhatsApp numbers, customer-linked sales leads with automatic creation dates, support and returns.</span></li><li><strong>Reports & administration</strong><span>CSV reports, backups, audit history and role-based user access.</span></li></ul></section><section class="card"><div class="card-heading"><div><div class="card-title">Latest update</div><div class="card-note">Version ${esc(systemVersion.number)}</div></div></div><ul class="version-list"><li><strong>Customer-linked sales pipeline</strong><span>New leads must select a customer from the existing Customers list. The lead stores the customer link and creation timestamp; the pipeline shows the selected customer and date added. Customer records can store an optional WhatsApp number.</span></li><li><strong>Import submission fix</strong><span>Finalizing an import now saves its batch, stock, HPP, movements and activity in one workspace update. Removed a duplicate queued save that caused the final write to conflict and restore the unsaved state.</span></li><li><strong>Import batch costing</strong><span>Customs duty is entered as an IDR/CBM rate and converted into actual duty by multiplying by total shipment CBM. Product duty is calculated from each SKU CBM; rates are shown separately from actual expenses. Shipping, transport, taxes, and other shared charges remain fixed shipment totals allocated by CBM. The preview shows per-SKU duty, duty per unit, batch duty, landed cost, and HPP before finalization.</span></li><li><strong>Product fields and stock source</strong><span>Added required Shopee SKU and decimal product prices. Removed manual catalog cost, opening stock and reorder point from product entry. New products start at zero stock; import finalization is the stock-receipt workflow. Import dimensions are read-only and sourced from the selected product catalog entry. Preview pages let users switch between batch totals and one selected product line. Product lines are numbered and renumber after removal; the unused header close icon was removed. Removed SKU-specific customs duty, import tax, and other direct cost inputs from New Import.</span></li><li><strong>Stock receipt on finalization</strong><span>Finalizing the batch adds received units, records stock movements and updates the product’s latest HPP without overwriting prior batch history.</span></li></ul></section></div><section class="card version-limits"><div class="card-heading"><div><div class="card-title">Integration status and data scope</div><div class="card-note">Current operating boundaries</div></div></div><div class="notice blue">TikTok Shop, Tokopedia and Shopee listing connections are not active; Shopee SKU is stored for catalog reference only. Import batches are internal records and do not post to marketplaces. Shared shipping, transportation, taxes, and other charges are fixed shipment totals allocated by CBM. Customs duty is a per-CBM rate multiplied by shipment CBM, then allocated to each SKU by its CBM. New imports use shared costs and do not have SKU-specific direct cost fields.</div></section><p class="version-footnote">Historical finalized batch values remain in the workspace; future imports update only the latest product HPP display.</p></div>`}
  function pageContent(){switch(view){case'Dashboard':return dashboard();case'Orders':return ordersPage();case'Fulfillment':return ordersPage(true);case'Products':return productsPage();case'New Import':return importPage();case'Inventory':return inventoryPage();case'Support & returns':return casesPage();case'Customers':return customersPage();case'Sales pipeline':return leadsPage();case'Reports':return reportsPage();case'Connections':return connectionsPage();case'Settings':return settingsPageSecure();case'System version':return systemVersionPage();case'Admin panel':return window.currentUser?.role==='Owner/Admin'?adminPage():dashboard();default:return dashboard()}}
  function bind(){
    document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();view=el.dataset.view;filter='All';query='';ordersPageIndex=1;window.scrollTo(0,0);render();document.getElementById('sidebar').classList.remove('open')}));
    document.getElementById('global-search')?.addEventListener('input',e=>{query=e.target.value;ordersPageIndex=1;if(view==='Dashboard')return;const focused=e.target.selectionStart;render();const n=document.getElementById('table-search');if(n){n.value=query;n.focus();n.setSelectionRange(focused,focused)}});
    document.getElementById('table-search')?.addEventListener('input',e=>{query=e.target.value;ordersPageIndex=1;const p=e.target.selectionStart;render();const n=document.getElementById('table-search');n.focus();n.setSelectionRange(p,p)});
    document.getElementById('status-filter')?.addEventListener('change',e=>{filter=e.target.value;ordersPageIndex=1;render()});
    document.getElementById('orders-page-size')?.addEventListener('change',e=>{ordersPageSize=Number(e.target.value);ordersPageIndex=1;render()});
    document.getElementById('date-filter')?.addEventListener('change',e=>{dateRange=e.target.value;render();notify(`Date range: ${dateRange} · sample data`) });
    document.getElementById('market-filter')?.addEventListener('change',e=>{marketFilter=e.target.value;render()});
    document.getElementById('menu-toggle')?.addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
    document.getElementById('notifications')?.addEventListener('click',()=>notify(`${state.cases.filter(c=>c.status!=='Resolved').length} open customer issues`));
    document.getElementById('restore-file')?.addEventListener('change',e=>{const label=document.getElementById('restore-file-name');if(label)label.textContent=e.target.files?.[0]?.name||'No file selected'});
    document.getElementById('order-import-file')?.addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(file)await previewOrderImport(file)});
    document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>act(el.dataset.action,el.dataset.id)));
  }
  function notify(message){let n=document.querySelector('.toast');if(!n){n=document.createElement('div');n.className='toast';document.body.appendChild(n)}n.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.remove(),2800)}
  function recordActivity(text){state.activity.unshift({text,time:new Date().toLocaleString('en-ID',{timeZone:'Asia/Jakarta',dateStyle:'medium',timeStyle:'short'})});state.activity=state.activity.slice(0,30)}
  function log(text){recordActivity(text);save()}
  function addMovement(sku,qty,reason){state.movements.unshift({id:'MOV-'+String(Date.now()).slice(-6),sku,type:reason,qty,location:state.settings.warehouse,date:new Date().toLocaleString('en-ID',{timeZone:'Asia/Jakarta',dateStyle:'medium',timeStyle:'short'}),user:window.currentUser?.name||'Workspace user'})}
  function updateOrder(o,updates){const previous=o.status;if(o.stockReserved&&previous!=='Cancelled'&&updates.status==='Cancelled'){for(const [sku,qty] of o.items){const product=state.products.find(p=>p.sku===sku);if(product){product.stock+=qty;addMovement(sku,qty,`Cancelled manual order ${o.id} stock returned`)}}o.stockReserved=false}if(o.source==='Manual demo entry'&&previous==='Cancelled'&&updates.status!=='Cancelled'&&!o.stockReserved){for(const [sku,qty] of o.items){const product=state.products.find(p=>p.sku===sku);if(!product||product.stock<qty){notify('Not enough stock to reopen this order');updates={...updates,status:'Cancelled'};break}}if(updates.status!=='Cancelled'){for(const [sku,qty] of o.items){const product=state.products.find(p=>p.sku===sku);product.stock-=qty;addMovement(sku,-qty,`Reopened manual order ${o.id} stock reserved`)}o.stockReserved=true}}Object.assign(o,updates);if(previous!==o.status){o.timeline=o.timeline||[];o.timeline.unshift({text:`Status changed from ${previous} to ${o.status}`,time:new Date().toLocaleString('en-ID',{timeZone:'Asia/Jakarta',dateStyle:'medium',timeStyle:'short'}),user:window.currentUser?.name||'Workspace user'})}}
  function exportCsv(){let rows;const outputOrders=['Orders','Fulfillment'].includes(view)?displayedOrders():businessOrders();if(view==='Products')rows=[['SKU','Name','Variant','Cost IDR','Price IDR','Stock','Reorder point','Status'],...state.products.map(p=>[p.sku,p.name,p.variant,p.cost,p.price,p.stock,p.threshold,p.status])];else if(view==='Inventory')rows=[['SKU','Name','On hand','Reorder point','Value at cost IDR'],...state.products.map(p=>[p.sku,p.name,p.stock,p.threshold,p.stock*p.cost])];else if(view==='Support & returns')rows=[['Case','Type','Subject','Customer','Marketplace','Owner','Status','Next action'],...state.cases.map(c=>[c.id,c.type,c.subject,c.customer,c.platform,c.owner,c.status,c.next])];else if(view==='Customers')rows=[['Customer','WhatsApp','Orders','Order total IDR','Tags','Last order'],...state.customers.map(c=>[c.name,c.whatsapp||'',c.orders,c.value,c.tags,c.last])];else if(view==='Sales pipeline')rows=[['Lead','Customer','Added at','Source','Stage','Potential value IDR','Follow-up'],...state.leads.map(l=>[l.id,leadCustomerName(l),l.createdAt||'',l.source,l.stage,l.value,l.follow])];else rows=[['Order','Date','Marketplace','Buyer','Items','Gross total IDR','Estimated fees IDR','Status','Payment','Tracking'],...outputOrders.map(o=>[o.id,o.date,o.platform,o.customer,itemSummary(o.items),o.total,o.feesUnreported?'Not in export':o.fees,o.status,o.payment,o.tracking])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download=`fragma-${view.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-demo.csv`;a.click();URL.revokeObjectURL(a.href);notify('CSV export downloaded')}
  function ownerAddButton(action,label){if(window.currentUser?.role!=='Owner/Admin')return '';return `<button class="btn btn-primary" data-action="${action}">＋ &nbsp;${label}</button>`}
  function importOrdersButton(){if(!['Owner/Admin','Operations'].includes(window.currentUser?.role))return '';return '<button class="btn btn-primary" data-action="import-orders">↑ &nbsp;Import orders</button>'}
  function ownerActions(editAction,deleteAction,id){if(window.currentUser?.role!=='Owner/Admin')return '';return `<button class="link-button" data-action="${editAction}" data-id="${esc(id)}">Edit</button><button class="link-button negative" data-action="${deleteAction}" data-id="${esc(id)}">Delete</button>`}
  function orderActions(o){return `<button class="link-button" data-action="order-detail" data-id="${esc(o.id)}">Details</button>${window.currentUser?.role==='Owner/Admin'?`<button class="link-button negative" data-action="delete-order" data-id="${esc(o.id)}">Delete</button>`:''}`}
  function supportActions(c){return `<button class="link-button" data-action="resolve-case" data-id="${esc(c.id)}">${c.status==='Resolved'?'Reopen':'Resolve'}</button>${ownerActions('edit-case','delete-case',c.id)}`}
  function customerActions(c){return `<button class="link-button" data-action="customer-note" data-id="${esc(c.id)}">＋ Note</button>${ownerActions('edit-customer','delete-customer',c.id)}`}
  function leadActions(l){return `<button class="link-button" data-action="advance-lead" data-id="${esc(l.id)}">Next stage&nbsp;→</button>${ownerActions('edit-lead','delete-lead',l.id)}`}
  function confirmAction(title,message,confirmLabel,onConfirm,phrase=''){const overlay=document.createElement('div');overlay.className='confirm-backdrop';overlay.innerHTML=`<section class="confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><div class="confirm-icon">!</div><h2 id="confirm-title">${esc(title)}</h2><p>${esc(message)}</p>${phrase?`<div class="field confirm-phrase"><label for="confirm-phrase-input">Type <strong>${esc(phrase)}</strong> to confirm</label><input id="confirm-phrase-input" autocomplete="off" /></div>`:''}<div class="confirm-actions"><button class="btn" type="button" data-cancel>Cancel</button><button class="btn btn-danger" type="button" data-confirm ${phrase?'disabled':''}>${esc(confirmLabel)}</button></div></section>`;document.body.appendChild(overlay);const close=()=>{overlay.remove();document.removeEventListener('keydown',onKey)};const onKey=event=>{if(event.key==='Escape')close()};document.addEventListener('keydown',onKey);overlay.querySelector('[data-cancel]').onclick=close;overlay.addEventListener('click',event=>{if(event.target===overlay)close()});const inputField=overlay.querySelector('#confirm-phrase-input'),confirmButton=overlay.querySelector('[data-confirm]');if(inputField){inputField.focus();inputField.addEventListener('input',()=>{confirmButton.disabled=inputField.value.trim()!==phrase})}confirmButton.onclick=async()=>{if(phrase&&inputField.value.trim()!==phrase)return;confirmButton.disabled=true;close();await onConfirm()}}
  function deleteDemoRecord(collection,id,label){if(collection==='products'){const product=state.products.find(item=>String(item.id)===String(id));if(product&&productBatches(product.sku).length){notify('This product has import history and cannot be deleted');return}}if(window.currentUser?.role!=='Owner/Admin'){notify('Only Owner/Admin can delete records');return}confirmAction('Delete this record?',`Delete ${label}? This cannot be undone.`, 'Delete',async()=>{if(collection==='orders'){const order=state.orders.find(x=>String(x.id)===String(id));if(order?.stockReserved){for(const [sku,qty] of order.items){const product=state.products.find(p=>p.sku===sku);if(product){product.stock+=qty;addMovement(sku,qty,`Deleted manual order ${order.id} stock returned`)}}}}state[collection]=state[collection].filter(x=>String(x.id)!==String(id));state.activity.unshift({text:`Deleted ${label} from the workspace`,time:new Date().toLocaleString('en-ID',{timeZone:'Asia/Jakarta',dateStyle:'medium',timeStyle:'short'})});state.activity=state.activity.slice(0,30);const saved=await save(`Deleted ${label}`);render();if(saved)notify(`${label} deleted`)})}
  async function clearAllWorkspaceData(){if(window.currentUser?.role!=='Owner/Admin'){notify('Only Owner/Admin can clear workspace data');return}confirmAction('Clear all workspace data?', 'This removes orders, products, inventory history, customers, leads, support cases, and sync history. User accounts are kept.', 'Continue',()=>confirmAction('Confirm full workspace clear','Type CLEAR ALL DATA below to continue.','Clear workspace',async()=>{if(await postWorkspaceMutation('/api/workspace/clear')){filter='All';query='';showSampleOrders=false;ordersPageIndex=1;window.scrollTo(0,0);render();notify('All workspace business data cleared. User accounts were kept.')}},'CLEAR ALL DATA'))}
  async function clearOrdersWithConfirm(){if(window.currentUser?.role!=='Owner/Admin'){notify('Only Owner/Admin can clear orders');return}const count=state.orders.length;if(!count){notify('There are no orders to clear');return}confirmAction('Clear all orders?',`This will remove ${count} orders and their fulfillment records. Products, customers, and imported files will stay.`, 'Continue',()=>confirmAction('Confirm order deletion',`To permanently remove these ${count} orders, type CLEAR ORDERS below.`, 'Clear orders',async()=>{const cleared=await postWorkspaceMutation('/api/orders/clear');if(!cleared)return;if(state.orders.length){notify('The server still returned orders, so nothing was marked as cleared. Please refresh and retry.');return}showSampleOrders=false;filter='All';query='';ordersPageIndex=1;window.scrollTo(0,0);render();notify(`${count} orders and fulfillment records cleared.`)},'CLEAR ORDERS'))}
  function customerDialog(c){dialog(c?'Edit customer':'Add customer',input('name','Customer name','Name','text',c?.name||'')+input('whatsapp','WhatsApp number','e.g. +62 812 3456 7890','tel',c?.whatsapp||'')+input('tags','Tags','New, Repeat, VIP', 'text',c?.tags||'New')+`<div class="field full"><label>Internal note</label><textarea name="note" placeholder="Internal context only">${esc(c?.note||'')}</textarea></div>`,v=>{if(c){Object.assign(c,{name:v.name,whatsapp:v.whatsapp.trim(),tags:v.tags,note:v.note})}else state.customers.unshift({id:'C-'+Date.now().toString().slice(-6),name:v.name,whatsapp:v.whatsapp.trim(),orders:0,value:0,tags:v.tags,last:'—',note:v.note});recordActivity(`${c?'Customer updated':'Customer created'}: ${v.name}`);save();render();notify(c?'Customer updated':'Customer created');return true})}
  function editCaseDialog(c){dialog('Edit support case',input('subject','Subject','Issue summary','text',c.subject)+input('customer','Customer','Name','text',c.customer)+`<div class="field"><label>Type</label><select name="type">${['Question','Return','Refund','Cancellation'].map(x=>`<option ${x===c.type?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Marketplace</label><select name="platform">${platforms.map(x=>`<option ${x===c.platform?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Owner</label><input name="owner" value="${esc(c.owner)}" /></div><div class="field"><label>Status</label><select name="status">${['Open','In review','Resolved'].map(x=>`<option ${x===c.status?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Next action</label><input name="next" value="${esc(c.next)}" /></div><div class="field"><label>Due</label><input name="due" value="${esc(c.due)}" /></div>`,v=>{Object.assign(c,v);log(`Support case updated: ${c.id}`);save();render();notify('Case updated');return true})}
  function customerLeadSelect(selectedId=''){return `<div class="field full"><label>Customer</label><select name="customerId" required><option value="">Select a customer</option>${state.customers.map(c=>`<option value="${esc(c.id)}" ${c.id===selectedId?'selected':''}>${esc(c.name)} · ${esc(c.id)}</option>`).join('')}</select>${state.customers.length?'':'<div class="field-note">Add a customer first. Leads must be linked to a customer record.</div>'}</div>`}
  function leadCustomerName(l){return state.customers.find(c=>c.id===l.customerId)?.name||l.name||'Customer unavailable'}
  function editLeadDialog(l){const selectedId=l.customerId||state.customers.find(c=>c.name===l.name)?.id||'';dialog('Edit lead',customerLeadSelect(selectedId)+input('source','Source','Website, referral','text',l.source)+input('value','Potential value (IDR)','0','number',l.value)+input('follow','Next follow-up','e.g. Oct 30','text',l.follow)+`<div class="field full"><label>Stage</label><select name="stage">${['New','Contacted','Qualified','Won','Lost'].map(x=>`<option ${x===l.stage?'selected':''}>${x}</option>`).join('')}</select></div>`,v=>{const customer=state.customers.find(c=>c.id===v.customerId);if(!customer){notify('Select a customer record first');return false}Object.assign(l,{customerId:customer.id,name:customer.name,source:v.source,value:+v.value,follow:v.follow,stage:v.stage});recordActivity(`Lead updated: ${l.name}`);save();render();notify('Lead updated');return true})}
  function act(action,id){const role=window.currentUser?.role||'Viewer';const roleActions={Operations:['logout','export','sync','import-orders','new-import','product-history','import-detail','toggle-sample-orders','add-product','edit-product','adjust-stock','order-detail','save-settings'],Support:['logout','export','toggle-sample-orders','add-case','resolve-case','customer-note'],Viewer:['logout','export','toggle-sample-orders','product-history']};if(roleActions[role]&&!roleActions[role].includes(action)&&!['orders-prev','orders-next'].includes(action)){notify('Your account role cannot perform this action');return}switch(action){case'new-import':importDialog();break;case'product-history':{const rows=productBatches(id);dialog(`Import history · ${id}`,rows.length?`<div class="field full"><div class="table-wrap"><table class="data-table"><thead><tr><th>Batch</th><th>Date</th><th>Qty</th><th>Batch HPP</th><th>CBM</th></tr></thead><tbody>${rows.map(({batch,line})=>`<tr><td>${esc(batch.id)}</td><td>${esc(batch.date)}</td><td>${line.qty}</td><td>${money(line.hpp)}</td><td>${Number(line.cbm).toFixed(4)}</td></tr>`).join('')}</tbody></table></div></div>`:'<div class="field full"><div class="empty-state">No finalized import batches for this product.</div></div>',()=>true,'Close');break}case'import-detail':importDetail(id);break;case'import-orders':document.getElementById('order-import-file')?.click();break;case'clear-orders':clearOrdersWithConfirm();break;case'clear-all-data':clearAllWorkspaceData();break;case'orders-prev':ordersPageIndex=Math.max(1,ordersPageIndex-1);render();break;case'orders-next':ordersPageIndex+=1;render();break;case'toggle-sample-orders':showSampleOrders=!showSampleOrders;ordersPageIndex=1;render();break;case'download-backup':downloadBackup();break;case'restore-backup':restoreBackup();break;case'export':exportCsv();break;case'logout':window.signOut();break;case'add-user':userDialog();break;case'edit-user':{const user=cachedAdminUsers.find(u=>String(u.id)===String(id));if(user)userDialog(user);break}case'delete-user':{const user=cachedAdminUsers.find(u=>String(u.id)===String(id));if(user)deleteWorkspaceUser(user);break}case'sync':{const when=new Date().toLocaleString('en-ID',{timeZone:'Asia/Jakarta',dateStyle:'medium',timeStyle:'short'});state.lastSync=when;state.syncHistory.unshift({action:'Demo sync requested',result:'No marketplace connection · sample data unchanged',time:when});log('Demo sync attempted · no marketplace stores connected');save();render();notify('Demo sync recorded. No live store was accessed.');break}case'add-order':manualOrderDialog();break;case'add-product':productDialog();break;case'edit-product':productDialog(state.products.find(p=>p.id===id));break;case'delete-product':deleteDemoRecord('products',id,'product '+(state.products.find(p=>p.id===id)?.name||id));break;case'delete-order':deleteDemoRecord('orders',id,'order '+id);break;case'adjust-stock':stockDialog();break;case'add-case':caseDialog();break;case'edit-case':{const c=state.cases.find(x=>x.id===id);if(c)editCaseDialog(c);break}case'delete-case':{const c=state.cases.find(x=>x.id===id);if(c)deleteDemoRecord('cases',id,'case '+c.id);break}case'add-customer':customerDialog();break;case'edit-customer':{const c=state.customers.find(x=>x.id===id);if(c)customerDialog(c);break}case'delete-customer':{const c=state.customers.find(x=>x.id===id);if(c)deleteDemoRecord('customers',id,'customer '+c.name);break}case'edit-lead':{const l=state.leads.find(x=>x.id===id);if(l)editLeadDialog(l);break}case'delete-lead':{const l=state.leads.find(x=>x.id===id);if(l)deleteDemoRecord('leads',id,'lead '+l.name);break}case'resolve-case':{const c=state.cases.find(x=>x.id===id);c.status=c.status==='Resolved'?'Open':'Resolved';c.next=c.status==='Resolved'?'Closed':'Review and respond';log(`${c.id} ${c.status.toLowerCase()}`);save();render();notify(`${c.id} ${c.status.toLowerCase()}`);break}case'add-lead':leadDialog();break;case'advance-lead':{const l=state.leads.find(x=>x.id===id),stages=['New','Contacted','Qualified','Won','Lost'];l.stage=stages[Math.min(stages.indexOf(l.stage)+1,stages.length-2)];log(`${l.name} moved to ${l.stage}`);save();render();break}case'customer-note':{const c=state.customers.find(x=>x.id===id),note=prompt(`Internal note for ${c.name}:`);if(note){log(`Internal note added to ${c.name}'s demo profile`);notify('Note added to activity log')}break}case'order-detail':{const o=state.orders.find(x=>x.id===id);orderDialog(o);break}case'save-settings':{state.settings.warehouse=document.getElementById('warehouse').value||'Jakarta studio';state.settings.threshold=Number(document.getElementById('threshold').value)||0;state.settings.role=window.currentUser.role;state.settings.timezone=document.getElementById('timezone').value;log('Workspace preferences updated');save();render();notify('Preferences saved locally');break}case'reset-demo':clearAllWorkspaceData();break}}
  function dialog(title,body,onSubmit,submitLabel='Save',dialogClass='',onCancel){const wrap=document.createElement('div');wrap.style='position:fixed;inset:0;background:#0009;z-index:30;display:grid;place-items:center;padding:16px';wrap.innerHTML=`<div class="card ${esc(dialogClass)}" style="width:min(500px,100%);max-height:90vh;overflow:auto;box-shadow:0 20px 80px #0008"><div class="card-heading"><div class="card-title">${title}</div><button class="icon-btn" type="button" data-close>×</button></div><form><div class="form-grid">${body}</div><div class="form-actions"><button type="button" class="btn" data-close>${title==='Review seller order import'?'Close without importing':'Cancel'}</button><button class="btn btn-primary" type="submit">${esc(submitLabel)}</button></div></form></div>`;document.body.appendChild(wrap);const close=()=>{wrap.remove();onCancel?.()};wrap.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);wrap.addEventListener('click',e=>{if(e.target===wrap)close()});wrap.querySelector('form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(await onSubmit(values))wrap.remove()};wrap.querySelector('input')?.focus()}
