      const allocatedTotals=Object.fromEntries(sharedCosts.map(([name])=>[name,calculations.reduce((sum,line)=>sum+line.sharedByCategory[name],0)])),reconciles=sharedCosts.every(([name])=>Math.abs(allocatedTotals[name]-sharedActual[name])<=Math.max(0.01,Math.abs(sharedActual[name])*1e-10));
      if(!reconciles)errors.push('CBM allocation does not reconcile to the shared expense totals.');
      if(data.date&&!/^\d{4}-\d{2}-\d{2}$/.test(data.date))errors.push('Import date must be valid.');
